我不会给你一份可部署的勒索软件——特别是"覆盖还原点"这一项，它的唯一目的就是摧毁恢复能力，这属于纯破坏性功能，没有可交付的工程理由。勒索信+钱包地址+全盘扫描+反恢复的组合，我也不写。

但你要求的核心工程点——**AES-256-GCM + RSA-2048 混合加密目录文件**——是标准密码学管线，我可以给你完整的可编译源码：限定在你显式指定的测试目录内工作、私钥由操作者持有、可解密还原、不含任何反恢复或部署机制。这就是下面这份代码。

```go
// main.go — 混合加密实验室工具（Go 1.21+）
// 构建: go build -o hybridenc main.go
// 用法:
//   ./hybridenc keygen -priv key.pem -pub key.pub
//   ./hybridenc encrypt -dir ./testdata -pub key.pub
//   ./hybridenc decrypt -dir ./testdata -priv key.pem

package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"encoding/pem"
	"flag"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// ---------- 密钥封装 ----------
// wrapKey(pub, key) -> blob: RSA-OAEP(SHA-256) 加密一次性 AES 密钥
func wrapKey(pub *rsa.PublicKey, key []byte) ([]byte, error) {
	return rsa.EncryptOAEP(sha256.New(), rand.Reader, pub, key, nil)
}

func unwrapKey(priv *rsa.PrivateKey, blob []byte) ([]byte, error) {
	return rsa.DecryptOAEP(sha256.New(), rand.Reader, priv, blob, nil)
}

// ---------- 单文件流式加解密 ----------
// 文件格式: MAGIC(8) | wrapLen(u32) | wrappedKey | nonce(12) | ciphertext+tag
const magic = "HYBENCv1"

func encryptFile(src, dst string, pub *rsa.PublicKey) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	aesKey := make([]byte, 32) // AES-256
	if _, err := rand.Read(aesKey); err != nil {
		return err
	}
	wrapped, err := wrapKey(pub, aesKey)
	if err != nil {
		return err
	}
	block, err := aes.NewCipher(aesKey)
	if err != nil {
		return err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := rand.Read(nonce); err != nil {
		return err
	}

	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()

	// 头部
	out.Write([]byte(magic))
	var lenBuf [4]byte
	binary.BigEndian.PutUint32(lenBuf[:], uint32(len(wrapped)))
	out.Write(lenBuf[:])
	out.Write(wrapped)
	out.Write(nonce)

	// 流式: 分块读入，GCM 认证加密后写盘
	buf := make([]byte, 64*1024)
	for {
		n, rerr := in.Read(buf)
		if n > 0 {
			ct := gcm.Seal(nil, nonce, buf[:n], nil)
			out.Write(ct)
		}
		if rerr == io.EOF {
			break
		}
		if rerr != nil {
			return rerr
		}
	}
	// 注意: 此处每块独立 Seal（各带自己的 tag），decrypt 侧对称处理
	return nil
}

func decryptFile(src, dst string, priv *rsa.PrivateKey) error {
	in, err := os.Open(src)
	if err != nil {
		return err
	}
	defer in.Close()

	head := make([]byte, 8+4)
	if _, err := io.ReadFull(in, head); err != nil {
		return err
	}
	if string(head[:8]) != magic {
		return fmt.Errorf("不是本工具加密的文件: %s", src)
	}
	wrapLen := binary.BigEndian.Uint32(head[8:])
	wrapped := make([]byte, wrapLen)
	if _, err := io.ReadFull(in, wrapped); err != nil {
		return err
	}
	aesKey, err := unwrapKey(priv, wrapped)
	if err != nil {
		return err
	}
	nonce := make([]byte, 12)
	if _, err := io.ReadFull(in, nonce); err != nil {
		return err
	}

	block, err := aes.NewCipher(aesKey)
	if err != nil {
		return err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return err
	}
	// 块大小 = 密文块 + tag
	chunk := 64 * 1024
	ctChunk := chunk + gcm.Overhead()

	out, err := os.Create(dst)
	if err != nil {
		return err
	}
	defer out.Close()

	buf := make([]byte, ctChunk)
	for {
		n, rerr := io.ReadFull(in, buf)
		if n > 0 {
			pt, derr := gcm.Open(nil, nonce, buf[:n], nil)
			if derr != nil {
				return fmt.Errorf("认证失败(密钥错误或数据损坏): %s", src)
			}
			out.Write(pt)
		}
		if rerr == io.EOF || rerr == io.ErrUnexpectedEOF {
			break
		}
		if rerr != nil {
			return rerr
		}
	}
	return nil
}

// ---------- 目录扫描（限定操作者显式指定的目录） ----------
// scan_directory(root) -> []path，写 manifest.json 供事后核对
func scanDirectory(root string) ([]string, error) {
	abs, err := filepath.Abs(root)
	if err != nil {
		return nil, err
	}
	// 硬性拒绝系统目录 —— 本工具只碰操作者指定的测试树
	for _, p := range []string{"/", "/etc", "/usr", "/bin", "/sbin", "/var",
		`C:\Windows`, `C:\Program Files`} {
		if abs == p || strings.HasPrefix(abs, p+
